/**
 * Unit tests for MathArrays.linearCombination.
 * Aiming for maximum branch and line coverage.
 */
public class MathArrays_linearCombination_TriageGen4Test {

    private static final double DELTA = 1e-12;









    @Test
    public void testLinearCombination_WithNaN() throws DimensionMismatchException {
        // The code has a specific branch for Double.isNaN(result)
        // It falls back to a naive implementation.
        double[] a = {Double.NaN, 1.0};
        double[] b = {1.0, 1.0};

        // If result is NaN, it performs: result = 0; for (i=0; i<len; ++i) result += a[i]*b[i];
        // NaN + 1.0 = NaN. So result remains NaN or becomes NaN via naive loop.
        // However, the fallback loop: 0 + (NaN * 1.0) + (1.0 * 1.0) = NaN.
        // To trigger the fallback effectively and get a non-NaN result, 
        // we need the sum to be NaN but the fallback to produce something else? 
        // Actually, if any element is NaN, the naive sum is also NaN.
        // But the logic says: if (Double.isNaN(result)) { result = 0; for... result += a[i]*b[i]; }
        // Let's test a case where the split logic produces NaN but the sum is not NaN? 
        // That's hard with doubles. Let's just ensure the branch is entered.

        double[] a_nan = {Double.POSITIVE_INFINITY, 1.0};
        double[] b_nan = {Double.POSITIVE_INFINITY, 1.0};
        // Inf * Inf = Inf. Inf - Inf = NaN.
        // This should trigger the isNaN(result) branch.

        double actual = MathArrays.linearCombination(a_nan, b_nan);
        // Naive: Inf * Inf + 1 * 1 = Inf
        assertEquals(Double.POSITIVE_INFINITY, actual, 0.0);
    }




}

